#include "../RightDisplay/AudioBridgeRealtime/hal.hpp"
#include <bit>
#include <iostream>
#include <thread>
#include <functional>
#include <limits>
#include <algorithm>
using namespace bridge;
namespace {
size_t assertions=0,cases=0;
void check(bool result){++assertions;if(!result)throw std::runtime_error("assertion "+std::to_string(assertions)+" failed");}
void near(double a,double b,double tolerance=1e-7){check(std::abs(a-b)<=tolerance);}
void rejects(const std::function<void()>& f){bool threw=false;try{f();}catch(const std::exception&){threw=true;}check(threw);}
void run(const char* name,const std::function<void()>& f){f();++cases;std::cout<<"PASS "<<name<<'\n';}
bool bits(Frame a,Frame b){return std::bit_cast<uint32_t>(a.l)==std::bit_cast<uint32_t>(b.l)&&std::bit_cast<uint32_t>(a.r)==std::bit_cast<uint32_t>(b.r);}
AudioStreamBasicDescription pcm(bool planar=false){AudioStreamBasicDescription a{};a.mSampleRate=48000;a.mFormatID=kAudioFormatLinearPCM;a.mFormatFlags=kAudioFormatFlagIsFloat|kAudioFormatFlagIsPacked|(planar?kAudioFormatFlagIsNonInterleaved:0);a.mBytesPerFrame=planar?4:8;a.mBytesPerPacket=a.mBytesPerFrame;a.mFramesPerPacket=1;a.mChannelsPerFrame=2;a.mBitsPerChannel=32;return a;}
Device device(std::string uid="A",uint32_t id=12){Device d;d.uid=uid;d.id=id;d.name="same name";d.rate=48000;d.alive=1;d.channels=2;d.buffer=256;d.maxBlock=256;d.stereoMap=true;d.transport=kAudioDeviceTransportTypeHDMI;d.buffers={2};d.streams.push_back({44,pcm(),pcm(),0});return d;}
}
int main(){try{
run("ring wraparound FIFO / timestamps",[]{Ring r(8);for(int round=0;round<40;++round){for(int i=0;i<8;++i)check(r.push({{float(round*8+i),-float(i)},uint64_t(i+1)}));check(r.fill()==8);for(int i=0;i<8;++i){TaggedFrame f{};check(r.pop(f));check(f.pcm.l==float(round*8+i)&&f.publishedHost==uint64_t(i+1));}check(r.fill()==0);}});
run("under/overrun without data overwrite",[]{Ring r(2);TaggedFrame f{};check(!r.pop(f)&&r.underrun==1);check(r.push({{1,2},0})&&r.push({{3,4},0}));check(!r.push({{5,6},0})&&r.overrun==1);check(r.pop(f)&&f.pcm.l==1);check(r.pop(f)&&f.pcm.l==3);rejects([]{Ring bad(3);});});
run("SPSC separate threads 100000 frames",[]{Ring r(1024);std::atomic<bool> correct{true};std::thread producer([&]{for(int i=0;i<100000;++i){while(!r.push({{float(i),-float(i)},uint64_t(i)}))std::this_thread::yield();}});std::thread consumer([&]{for(int i=0;i<100000;++i){TaggedFrame f{};while(!r.pop(f))std::this_thread::yield();if(f.pcm.l!=float(i)||f.pcm.r!=-float(i)||f.publishedHost!=uint64_t(i))correct=false;}});producer.join();consumer.join();check(correct&&r.fill()==0);});
run("unity bit equality including signed zero and low level",[]{Gain g;for(float f:{0.F,-0.F,1.F,-1.F,1e-20F,std::numeric_limits<float>::denorm_min()})check(bits(g.process({f,-f}),{f,-f}));});
run("fixture determinism and normalized full scale",[]{for(auto name:{"silence","sine","low","near","full","impulse","phase","channels","sweep"}){auto a=fixture(name),b=fixture(name);check(a.size()==96000);for(size_t i=0;i<a.size();++i){check(bits(a[i],b[i]));check(std::abs(a[i].l)<=1&&std::abs(a[i].r)<=1);}}rejects([]{fixture("unknown");});});
run("unity engine bit equality across wraps",[]{auto f=fixture("channels");Engine e(f,1024,512,256);e.prime(1);Frame out[256];size_t index=0;for(int block=0;block<800;++block){check(e.render(out,256,1,1000+block));for(auto x:out){check(bits(x,f[index%f.size()]));++index;}}check(e.ring.fill()==512&&e.telemetry.minFill==256&&e.telemetry.maxFill==512);});
run("requested gain / measured RMS amplitude",[]{auto f=fixture("sine");Gain g(.25F);double input=0,output=0;for(auto x:f){auto y=g.process(x);input+=double(x.l)*x.l;output+=double(y.l)*y.l;check(y.r==y.l);}near(std::sqrt(output/input),.25,1e-12);});
run("mute zero leakage / consumer continues",[]{Engine e(fixture("full"),1024,512,256);e.prime(1);e.commandMute(true);Frame out[256];check(e.render(out,256,1,10));check(e.render(out,256,1,20));for(size_t i=224;i<256;++i)check(bits(out[i],{}));check(e.render(out,256,1,30));for(auto f:out)check(bits(f,{}));check(e.cursor==1280&&e.ring.fill()==512);});
run("unmute restores saved attenuation with ramp",[]{Engine e(std::vector<Frame>(96000,{1,1}),1024,512,256,.25);e.prime(1);Frame out[256];e.commandMute(true);for(int i=0;i<3;++i)check(e.render(out,256,1,10+i));check(bits(out[255],{}));e.commandGain(.5);e.commandMute(false);check(e.render(out,256,1,20));check(out[0].l>0&&out[0].l<=.5/480+1e-7);check(e.render(out,256,1,21));check(bits(out[255],{.5,.5}));});
run("10ms ramp continuous / channel consistent",[]{Gain g(1);g.set(0);float previous=1;for(int i=0;i<480;++i){auto y=g.process({1,1});check(y.l==y.r&&y.l<=previous);check(previous-y.l<=1.F/480+1e-7F);previous=y.l;}check(g.current()==0);g.set(1);auto next=g.process({1,1});near(next.l,1.F/480);for(int i=1;i<480;++i)g.process({1,1});check(g.current()==1);});
run("mid-ramp retarget starts from actual gain",[]{Gain g(1);g.set(0);for(int i=0;i<240;++i)g.process({1,1});float prior=g.current();g.set(1);float next=g.process({1,1}).l;near(next-prior,(1-prior)/480);});
run("no L/R swap or cross contamination",[]{Gain g(.5);check(bits(g.process({.5,0}),{.25,0}));check(bits(g.process({0,.75}),{0,.375}));auto phase=fixture("phase");for(auto f:phase)check(g.process(f).l==-g.process(f).r);});
run("silence no noise or DC",[]{Engine e(fixture("silence"),1024,512,256,.3);e.prime(1);Frame out[256];for(int j=0;j<20;++j){check(e.render(out,256,1,10+j));for(auto f:out)check(bits(f,{}));}});
run("impulse direct path has no processing tail",[]{Engine e(fixture("impulse"),1024,512,256);e.prime(1);Frame out[256];check(e.render(out,256,1,10));check(bits(out[0],{.5,.25}));for(int i=1;i<256;++i)check(bits(out[i],{}));check(e.render(out,256,1,20));for(auto f:out)check(bits(f,{}));});
run("full scale no clipping at gain <=1",[]{auto f=fixture("full");for(float gain:{0.F,.01F,.5F,1.F}){Gain g(gain);for(auto x:f){auto y=g.process(x);check(std::abs(y.l)<=1&&std::abs(y.r)<=1);}}});
run("low level no integer quantization",[]{Gain g(.5);for(auto f:fixture("low")){auto y=g.process(f);check(y.l==f.l*.5F);if(f.l!=0)check(y.l!=0);}check(g.process({1e-20F,0}).l==5e-21F);});
run("invalid gain / fixture rejects",[]{rejects([]{Gain g(1.1);});rejects([]{Engine e({{NAN,0}});});Engine e(fixture("sine"));rejects([&]{e.commandGain(-1);});rejects([&]{e.commandGain(NAN);});rejects([]{Engine e(fixture("sine"),512,512,256);});});
run("epoch failure rejection preserves first cause",[]{for(auto reason:{Failure::TargetUnavailable,Failure::ContextChanged,Failure::FormatChanged,Failure::DeviceStopped,Failure::HALFailure,Failure::Stopped}){Gate g;check(g.accepts(1));g.invalidate(reason);check(!g.accepts(1)&&!g.accepts(2)&&g.epoch==2);g.invalidate(Failure::Stopped);check(g.failure==uint32_t(reason));}});
run("stale render callback silent / no consumption",[]{Engine e(fixture("sine"));e.prime(1);e.gate.invalidate(Failure::ContextChanged);Frame out[256];std::fill_n(out,256,Frame{1,1});check(!e.render(out,256,1,10));for(auto f:out)check(bits(f,{}));check(e.ring.fill()==512&&e.telemetry.staleCallbacks==1);});
run("engine underrun terminal / zero block",[]{Engine e(fixture("sine"));Frame out[256];check(!e.render(out,256,1,10));for(auto f:out)check(bits(f,{}));check(e.gate.failure==uint32_t(Failure::Underrun));});
run("latency components separate",[]{auto l=latency(512,256,48000);near(l.ringMs,10.6666666667,1e-8);near(l.bufferMs,5.3333333333,1e-8);rejects([]{latency(1,1,0);});});
run("internal residence measurement",[]{Engine e(fixture("sine"));e.prime(100);Frame out[256];check(e.render(out,256,1,110));check(e.telemetry.residenceFrames==256&&e.telemetry.residenceTicks==2560&&e.telemetry.maxResidenceTicks==10);});
run("ASBD Float32 interleaved / planar validation",[]{check(clientFormatAllowed(pcm()));check(clientFormatAllowed(pcm(true)));check(layoutAllowed({2},false)&&layoutAllowed({1,1},true));check(!layoutAllowed({1,1},false)&&!layoutAllowed({6},false));});
run("encoded / surround / rate / byte-stride rejected",[]{auto a=pcm();a.mFormatID='ac-3';check(!clientFormatAllowed(a)&&!physicalFormatAllowed(a));a=pcm();a.mSampleRate=32000;check(!clientFormatAllowed(a));a=pcm();a.mChannelsPerFrame=6;check(!clientFormatAllowed(a));a=pcm();a.mBytesPerPacket=4;check(!clientFormatAllowed(a));a=pcm();a.mFormatFlags|=kAudioFormatFlagIsBigEndian;check(!clientFormatAllowed(a));});
run("known physical signed PCM / unknown conversion rejected",[]{auto a=pcm();check(physicalFormatAllowed(a));a.mBitsPerChannel=24;a.mFormatFlags=kAudioFormatFlagIsSignedInteger;a.mBytesPerFrame=8;a.mBytesPerPacket=8;check(physicalFormatAllowed(a));a.mFormatFlags=0;check(!physicalFormatAllowed(a));a=pcm();a.mBitsPerChannel=24;check(!physicalFormatAllowed(a));});
run("UID explicit resolution / no default fallback",[]{auto a=device("A",12),b=device("B",13);check(resolveFrom({a,b},"B").id==13);rejects([&]{resolveFrom({a,b},"missing");});rejects([&]{resolveFrom({a,b},"");});rejects([&]{resolveFrom({a,a},"A");});});
run("same-name siblings / changed deviceID cannot migrate",[]{auto a=device("A",12),b=device("B",13);check(!contextMatches(a,b));b=a;b.id=13;check(!contextMatches(a,b));b=a;b.streams[0].client.mSampleRate=44100;check(!contextMatches(a,b));check(contextMatches(a,a));b=a;b.streams[0].client.mReserved=99;b.streams[0].physical.mReserved=13;check(contextMatches(a,b));});
run("eligibility refuses incomplete / unsupported properties",[]{auto d=device();check(eligibility(d)=="USABLE_DIRECT_PATH");d.stereoMap=false;check(eligibility(d)!="USABLE_DIRECT_PATH");d=device();d.rate=32000;check(eligibility(d)!="USABLE_DIRECT_PATH");d=device();d.alive=0;check(eligibility(d)=="TARGET_UNAVAILABLE");d=device();d.buffers={1,1};check(eligibility(d)!="USABLE_DIRECT_PATH");});
run("native rates / 10ms ramp / unity at all six rates",[]{for(double rate:{44100.,48000.,88200.,96000.,176400.,192000.}){check(supportedRate(rate));auto f=fixture("sine",2,rate);check(f.size()==size_t(rate*2));Engine e(std::vector<Frame>(size_t(rate*2),{1,1}),4096,512,256,1,rate);e.prime(1);e.commandMute(true);Frame out[256];size_t frames=0;while(frames<size_t(rate*.01)+256){check(e.render(out,256,1,100+frames));for(auto x:out){++frames;check(x.l==x.r);if(frames>=size_t(rate*.01))check(bits(x,{}));}}auto a=pcm();a.mSampleRate=rate;check(clientFormatAllowed(a)&&physicalFormatAllowed(a));auto d=device();d.rate=rate;d.streams[0].client=a;d.streams[0].physical=a;check(eligibility(d)=="USABLE_DIRECT_PATH");auto l=latency(512,256,rate);near(l.ringMs,512000/rate,1e-8);}});
run("external producer interface / no hidden fixture refill",[]{Engine e({},1024,512,256,1,48000,100,false);Frame input[512];for(size_t i=0;i<512;++i)input[i]={float(i)/512,-float(i)/512};check(e.publishPCM(input,512,10));Frame out[256];check(e.render(out,256,100,20));for(size_t i=0;i<256;++i)check(bits(out[i],input[i]));check(e.ring.fill()==256);check(!e.render(out,256,99,30));check(e.ring.fill()==256);e.gate.invalidate(Failure::Stopped);check(!e.publishPCM(input,256,40));});
run("AirPlay / virtual / aggregate are not software physical targets",[]{check(!physicalTransport(kAudioDeviceTransportTypeAirPlay));check(!physicalTransport(kAudioDeviceTransportTypeVirtual));check(!physicalTransport(kAudioDeviceTransportTypeAggregate));check(!physicalTransport(0));check(physicalTransport(kAudioDeviceTransportTypeDisplayPort));});
run("mismatched nominal versus stream rates rejected",[]{auto d=device();d.rate=192000;check(eligibility(d)=="UNSUPPORTED_PCM_FORMAT");check(!supportedRate(32000)&&!supportedRate(NAN));});
std::cout<<"RESULT cases="<<cases<<" assertions="<<assertions<<" PASS (offline only; no HAL start)\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
